insert into theories (id, canonical_name, aliases, summary, key_sources, origin) values
  ('stimulus_organism_response', 'Stimulus–Organism–Response (S-O-R)', array['S-O-R', 'SOR', 'S-O-R framework', 'Stimulus-Organism-Response model']::text[], 'Environmental stimuli shape internal cognitive and affective states, which in turn drive approach or avoidance responses.', array['Mehrabian & Russell (1974), An approach to environmental psychology']::text[], 'plan_1_3'),
  ('source_credibility', 'Source Credibility Theory', array['Source Credibility', 'Source Credibility Model']::text[], 'A message persuades more when its source is seen as expert, trustworthy and (in endorsement research) attractive.', array['Hovland, Janis & Kelley (1953), Communication and persuasion', 'Ohanian (1990), Journal of Advertising']::text[], 'plan_1_3'),
  ('uses_and_gratifications', 'Uses and Gratifications Theory', array['Uses & Gratifications', 'U&G', 'UGT']::text[], 'People actively choose media to satisfy needs such as information, entertainment, social interaction and self-expression.', array['Katz, Blumler & Gurevitch (1973), Public Opinion Quarterly']::text[], 'plan_1_3'),
  ('parasocial_interaction_theory', 'Parasocial Interaction Theory', array['Parasocial Interaction', 'Parasocial Relationship Theory', 'PSI theory']::text[], 'Audiences form one-sided, friendship-like relationships with media figures, which shape their attitudes and behaviour.', array['Horton & Wohl (1956), Psychiatry']::text[], 'plan_1_3'),
  ('social_identity', 'Social Identity Theory', array['Social Identity', 'SIT']::text[], 'Part of the self-concept comes from group memberships; people favour and act in line with groups they identify with.', array['Tajfel & Turner (1979), An integrative theory of intergroup conflict']::text[], 'plan_1_3'),
  ('consumer_brand_relationship', 'Consumer–Brand Relationship Theory', array['Consumer–Brand Relationship', 'Brand Relationship Theory']::text[], 'Consumers relate to brands as relationship partners; relationship quality explains loyalty and other brand outcomes.', array['Fournier (1998), Journal of Consumer Research']::text[], 'plan_1_3'),
  ('attribution', 'Attribution Theory', array[]::text[], 'People infer the causes of others'' behaviour (e.g. a firm''s motives) and these inferences shape their reactions.', array['Heider (1958), The psychology of interpersonal relations', 'Kelley (1973), American Psychologist']::text[], 'plan_1_3'),
  ('signaling', 'Signaling Theory', array['Signalling Theory']::text[], 'Under information asymmetry, observable signals (e.g. brands, certifications) convey unobservable quality to the less informed party.', array['Spence (1973), Quarterly Journal of Economics', 'Erdem & Swait (1998), Journal of Consumer Psychology']::text[], 'plan_1_3'),
  ('persuasion_knowledge_model', 'Persuasion Knowledge Model', array['PKM', 'Persuasion Knowledge']::text[], 'Consumers learn how persuasion works and use this knowledge to recognise and cope with persuasion attempts.', array['Friestad & Wright (1994), Journal of Consumer Research']::text[], 'plan_1_3'),
  ('planned_behavior', 'Theory of Planned Behavior', array['TPB', 'Theory of Planned Behaviour']::text[], 'Attitude, subjective norms and perceived behavioural control predict intention, which predicts behaviour.', array['Ajzen (1991), Organizational Behavior and Human Decision Processes']::text[], 'plan_1_3'),
  ('reasoned_action', 'Theory of Reasoned Action', array['TRA']::text[], 'Behavioural intention, formed by attitude and subjective norms, is the immediate antecedent of behaviour.', array['Fishbein & Ajzen (1975), Belief, attitude, intention, and behavior']::text[], 'added'),
  ('technology_acceptance_model', 'Technology Acceptance Model', array['TAM']::text[], 'Perceived usefulness and perceived ease of use drive attitudes toward and intention to use a technology.', array['Davis (1989), MIS Quarterly']::text[], 'added'),
  ('elaboration_likelihood_model', 'Elaboration Likelihood Model', array['ELM']::text[], 'Persuasion follows a central route (argument scrutiny) or a peripheral route (cues), depending on motivation and ability.', array['Petty & Cacioppo (1986), Communication and persuasion: Central and peripheral routes']::text[], 'added'),
  ('commitment_trust', 'Commitment–Trust Theory', array['Commitment–Trust Theory of Relationship Marketing']::text[], 'Trust and relationship commitment are the key mediating variables of successful relational exchange.', array['Morgan & Hunt (1994), Journal of Marketing']::text[], 'added'),
  ('social_exchange', 'Social Exchange Theory', array['SET']::text[], 'Relationships form and persist through reciprocal exchanges of costs and benefits.', array['Blau (1964), Exchange and power in social life']::text[], 'added'),
  ('self_congruity', 'Self-Congruity Theory', array['Self-Congruity', 'Self-Image Congruence']::text[], 'Consumers prefer brands whose image matches their actual or ideal self-concept.', array['Sirgy (1982), Journal of Consumer Research']::text[], 'added'),
  ('expectation_disconfirmation', 'Expectation–Disconfirmation Theory', array['Expectancy Disconfirmation Theory', 'EDT']::text[], 'Satisfaction results from comparing perceived performance with prior expectations.', array['Oliver (1980), Journal of Marketing Research']::text[], 'added')
insert into constructs (id, canonical_name, canonical_definition, definition_source, domain, parent_construct_id, origin) values
  ('social_media_marketing_activities', 'Social Media Marketing Activities', 'Consumers'' perception of a brand''s marketing efforts on social media, commonly as entertainment, interaction, trendiness, customisation and word of mouth.', 'Kim & Ko (2012), Journal of Business Research', 'social_media', null, 'plan_1_3'),
  ('smma_entertainment', 'Entertainment (SMMA)', 'The extent to which a brand''s social media content is perceived as fun and enjoyable.', 'Kim & Ko (2012), Journal of Business Research', 'social_media', 'social_media_marketing_activities', 'added'),
  ('smma_interaction', 'Interaction (SMMA)', 'The extent to which a brand''s social media lets users exchange opinions and talk with the brand and each other.', 'Kim & Ko (2012), Journal of Business Research', 'social_media', 'social_media_marketing_activities', 'added'),
  ('smma_trendiness', 'Trendiness (SMMA)', 'The extent to which a brand''s social media offers the latest, up-to-date information.', 'Kim & Ko (2012), Journal of Business Research', 'social_media', 'social_media_marketing_activities', 'added'),
  ('smma_customization', 'Customization (SMMA)', 'The extent to which a brand''s social media offers tailored information and services.', 'Kim & Ko (2012), Journal of Business Research', 'social_media', 'social_media_marketing_activities', 'added'),
  ('ewom', 'Electronic Word of Mouth', 'Positive or negative statements about a product, brand or firm made by consumers and shared with many others via the internet.', 'Hennig-Thurau, Gwinner, Walsh & Gremler (2004), Journal of Interactive Marketing', 'social_media', null, 'plan_1_3'),
  ('influencer_credibility', 'Influencer Credibility', 'The degree to which followers see an influencer as a believable source, typically through expertise, trustworthiness and attractiveness.', 'Ohanian (1990), Journal of Advertising', 'social_media', null, 'plan_1_3'),
  ('influencer_expertise', 'Influencer Expertise', 'The extent to which an influencer is seen as knowledgeable and skilled about the topic or product.', 'Ohanian (1990), Journal of Advertising', 'social_media', 'influencer_credibility', 'added'),
  ('influencer_trustworthiness', 'Influencer Trustworthiness', 'The extent to which an influencer is seen as honest and sincere in what they say.', 'Ohanian (1990), Journal of Advertising', 'social_media', 'influencer_credibility', 'added'),
  ('influencer_attractiveness', 'Influencer Attractiveness', 'The extent to which an influencer is seen as physically or socially appealing.', 'Ohanian (1990), Journal of Advertising', 'social_media', 'influencer_credibility', 'added'),
  ('parasocial_interaction', 'Parasocial Interaction', 'A follower''s illusory, one-sided sense of personal interaction and closeness with a media figure such as an influencer.', 'Horton & Wohl (1956), Psychiatry; Rubin, Perse & Powell (1985), Human Communication Research', 'social_media', null, 'plan_1_3'),
  ('customer_engagement', 'Customer Engagement', 'A customer''s psychological state and behaviour of interacting with a brand or brand community, with cognitive, emotional and behavioural dimensions.', 'Brodie, Hollebeek, Jurić & Ilić (2011), Journal of Service Research', 'social_media', null, 'plan_1_3'),
  ('user_generated_content', 'User-Generated Content', 'Media content created and published online by users rather than by the brand or professional media.', 'Daugherty, Eastin & Bright (2008), Journal of Interactive Advertising', 'social_media', null, 'plan_1_3'),
  ('brand_equity', 'Brand Equity', 'The differential effect that brand knowledge has on consumer response to the brand''s marketing.', 'Keller (1993), Journal of Marketing; Aaker (1991), Managing brand equity', 'branding', null, 'plan_1_3'),
  ('brand_awareness', 'Brand Awareness', 'The consumer''s ability to recognise or recall a brand.', 'Keller (1993), Journal of Marketing', 'branding', 'brand_equity', 'plan_1_3'),
  ('brand_image', 'Brand Image', 'Consumers'' perceptions of a brand as reflected by the associations held in memory.', 'Keller (1993), Journal of Marketing', 'branding', 'brand_equity', 'plan_1_3'),
  ('brand_trust', 'Brand Trust', 'The consumer''s willingness to rely on the brand''s ability to perform its stated function.', 'Chaudhuri & Holbrook (2001), Journal of Marketing', 'branding', null, 'plan_1_3'),
  ('brand_love', 'Brand Love', 'The degree of passionate emotional attachment a satisfied consumer has for a brand.', 'Carroll & Ahuvia (2006), Marketing Letters', 'branding', null, 'plan_1_3'),
  ('brand_authenticity', 'Brand Authenticity', 'The extent to which consumers see a brand as faithful to itself and true to its consumers (continuity, credibility, integrity, symbolism).', 'Morhart, Malär, Guèvremont, Girardin & Grohmann (2015), Journal of Consumer Psychology', 'branding', null, 'plan_1_3'),
  ('brand_attachment', 'Brand Attachment', 'The strength of the bond connecting the brand with the self, shown by brand–self connection and brand prominence.', 'Park, MacInnis, Priester, Eisingerich & Iacobucci (2010), Journal of Marketing', 'branding', null, 'plan_1_3'),
  ('perceived_csr', 'Perceived Corporate Social Responsibility', 'Consumers'' perception of the extent to which a firm meets its economic, legal, ethical and discretionary responsibilities to society.', 'Carroll (1979), Academy of Management Review; Sen & Bhattacharya (2001), Journal of Marketing Research', 'ethics', null, 'plan_1_3'),
  ('greenwashing_perception', 'Greenwashing Perception', 'Consumers'' belief that a firm misleads them about the environmental performance or benefits of its products or practices.', 'Chen & Chang (2013), Journal of Business Ethics', 'ethics', null, 'plan_1_3'),
  ('ethical_consumption', 'Ethical Consumption', 'Buying, using or avoiding products on the basis of ethical concerns such as environmental, social or animal-welfare issues.', 'Carrington, Neville & Whitwell (2010), Journal of Business Ethics', 'ethics', null, 'plan_1_3'),
  ('privacy_concern', 'Privacy Concern', 'An individual''s worry about how organisations collect, control and use their personal information.', 'Malhotra, Kim & Agarwal (2004), Information Systems Research', 'ethics', null, 'plan_1_3'),
  ('sponsorship_disclosure', 'Sponsorship Disclosure', 'A notice that informs the audience that content is paid for or sponsored by a brand.', 'Boerman, van Reijmersdal & Neijens (2012), Journal of Communication', 'ethics', null, 'plan_1_3'),
  ('consumer_skepticism', 'Consumer Skepticism', 'A general tendency to disbelieve the claims a firm or its advertising makes.', 'Obermiller & Spangenberg (1998), Journal of Consumer Psychology', 'ethics', null, 'plan_1_3'),
  ('purchase_intention', 'Purchase Intention', 'A consumer''s conscious plan or likelihood to buy a brand or product.', 'Spears & Singh (2004), Journal of Current Issues & Research in Advertising; Dodds, Monroe & Grewal (1991), Journal of Marketing Research', 'consumer_behavior', null, 'plan_1_3'),
  ('satisfaction', 'Satisfaction', 'The consumer''s evaluative judgement that consumption met or exceeded expectations.', 'Oliver (1980), Journal of Marketing Research', 'consumer_behavior', null, 'plan_1_3'),
  ('loyalty', 'Loyalty', 'A deeply held commitment to rebuy or repatronise a preferred brand or firm consistently in the future despite situational influences.', 'Oliver (1999), Journal of Marketing', 'consumer_behavior', null, 'plan_1_3'),
  ('wom_intention', 'Word-of-Mouth Intention', 'A consumer''s intention to say positive things about and recommend a brand or firm to others.', 'Zeithaml, Berry & Parasuraman (1996), Journal of Marketing', 'consumer_behavior', null, 'plan_1_3'),
  ('willingness_to_pay_premium', 'Willingness to Pay a Premium', 'The amount a consumer is willing to pay for a brand over comparable alternatives.', 'Netemeyer et al. (2004), Journal of Business Research', 'consumer_behavior', null, 'plan_1_3'),
  ('perceived_brand_ethicality', 'Perceived Brand Ethicality', 'Consumers'' overall perception that a brand behaves in a morally responsible way toward people, society and the environment.', 'Gom từ nhãn của các bài trong kho (2026); bước P3, định nghĩa do dự án tóm tắt, chưa đối chiếu nguồn kinh điển', 'ethics', null, 'added'),
  ('authentic_brand_ethicality', 'Authentic Brand Ethicality', 'Consumers'' perception that a brand''s ethical conduct is genuine and consistent rather than a marketing pose.', 'Gom từ nhãn của các bài trong kho (2026); bước P3, định nghĩa do dự án tóm tắt, chưa đối chiếu nguồn kinh điển', 'ethics', null, 'added'),
  ('perceived_brand_transparency', 'Perceived Brand Transparency', 'Consumers'' perception that a brand is open, clear and forthcoming about information that matters to them.', 'Gom từ nhãn của các bài trong kho (2026); bước P3, định nghĩa do dự án tóm tắt, chưa đối chiếu nguồn kinh điển', 'ethics', null, 'added'),
  ('customer_gratitude', 'Customer Gratitude', 'A customer''s felt appreciation toward a firm for benefits received that were seen as intended and valuable.', 'Gom từ nhãn của các bài trong kho (2026); bước P3, định nghĩa do dự án tóm tắt, chưa đối chiếu nguồn kinh điển', 'consumer_behavior', null, 'added'),
  ('perceived_quality', 'Perceived Quality', 'The consumer''s judgement of the overall excellence or superiority of a product or brand.', 'Zeithaml (1988), Journal of Marketing', 'consumer_behavior', null, 'added'),
  ('commitment', 'Commitment', 'A customer''s enduring desire to maintain a valued relationship with a brand or firm.', 'Morgan & Hunt (1994), Journal of Marketing', 'consumer_behavior', null, 'added'),
  ('brand_integrity', 'Brand Integrity', 'The perception that a brand is honest and keeps its promises, acting in line with its stated values.', 'Gom từ nhãn của các bài trong kho (2026); bước P3, định nghĩa do dự án tóm tắt, chưa đối chiếu nguồn kinh điển', 'branding', null, 'added'),
  ('perceived_ethicality', 'Perceived Ethicality', 'Consumers'' general perception that a firm, a brand or its conduct is ethical, without tying it to one particular object.', 'Gom từ nhãn của các bài trong kho (2026); bước P3, định nghĩa do dự án tóm tắt, chưa đối chiếu nguồn kinh điển', 'ethics', null, 'added'),
  ('perceived_value', 'Perceived Value', 'The consumer''s overall assessment of what is received relative to what is given.', 'Zeithaml (1988), Journal of Marketing', 'consumer_behavior', null, 'added'),
  ('brand_affect', 'Brand Affect', 'A brand''s potential to elicit a positive emotional response in the consumer as a result of using it.', 'Chaudhuri & Holbrook (2001), Journal of Marketing', 'branding', null, 'added')
